"377 :   private Node inlineFunction(
378 :       Node callNode, Node fnNode, String fnName) {
379 :     Node parent = callNode.getParent();
380 :     Node grandParent = parent.getParent();
381 : 
382 :     // TODO(johnlenz): Consider storing the callSite classification in the
383 :     // reference object and passing it in here.
384 :     CallSiteType callSiteType = classifyCallSite(callNode);
385 :     Preconditions.checkArgument(callSiteType != CallSiteType.UNSUPPORTED);
386 : 
387 :     // Store the name for the result. This will be used to
388 :     // replace "return expr" statements with "resultName = expr"
389 :     // to replace
390 :     String resultName = null;
391 :     boolean needsDefaultReturnResult = true;
392 :     switch (callSiteType) {
393 :       case SIMPLE_ASSIGNMENT:
394 :         resultName = parent.getFirstChild().getString();
395 :         break;
396 : 
397 :       case VAR_DECL_SIMPLE_ASSIGNMENT:
398 :         resultName = parent.getString();
399 :         break;
400 : 
401 :       case SIMPLE_CALL:
402 :         resultName = null;  // "foo()" doesn't need a result.
403 :         needsDefaultReturnResult = false;
404 :         break;
405 : 
406 :       case EXPRESSION:
407 :         resultName = getUniqueResultName();
408 :         needsDefaultReturnResult = false; // The intermediary result already
409 :                                           // has the default value.
410 :         break;
411 : 
412 :       case DECOMPOSABLE_EXPRESSION:
413 :         throw new IllegalStateException(
414 :             "Decomposable expressions must decomposed before inlining.");
415 : 
416 :       default:
417 :         throw new IllegalStateException("Unexpected call site type.");
418 :     }
419 : 
420 :     boolean isCallInLoop = NodeUtil.isWithinLoop(callNode);
421 : 
422 :     FunctionToBlockMutator mutator = new FunctionToBlockMutator(
423 :         compiler, this.safeNameIdSupplier);
424 : 
425 :     Node newBlock = mutator.mutate(
426 :         fnName, fnNode, callNode, resultName,
427 :         needsDefaultReturnResult, isCallInLoop);
428 : 
429 :     // TODO(nicksantos): Create a common mutation function that
430 :     // can replace either a VAR name assignment, assignment expression or
431 :     // a EXPR_RESULT.
432 :     Node greatGrandParent = grandParent.getParent();
433 :     switch (callSiteType) {
434 :       case VAR_DECL_SIMPLE_ASSIGNMENT:
435 :         // Remove the call from the name node.
436 :         parent.removeChild(parent.getFirstChild());
437 :         Preconditions.checkState(parent.getFirstChild() == null);
438 :         // Add the call, after the VAR.
439 :         greatGrandParent.addChildAfter(newBlock, grandParent);
440 :         break;
441 : 
442 :       case SIMPLE_ASSIGNMENT:
443 :         // The assignment is now part of the inline function so
444 :         // replace it completely.
445 :         Preconditions.checkState(NodeUtil.isExpressionNode(grandParent));
446 :         greatGrandParent.replaceChild(grandParent, newBlock);
447 :         break;
448 : 
449 :       case SIMPLE_CALL:
450 :         // If nothing is looking at the result just replace the call.
451 :         Preconditions.checkState(NodeUtil.isExpressionNode(parent));
452 :         grandParent.replaceChild(parent, newBlock);
453 :         break;
454 : 
455 :       case EXPRESSION:
456 :         // TODO(johnlenz): Maybe change this so that movable and decomposable
457 :         // expressions are handled the same way: The call is moved and
458 :         // then handled by one the three basic cases, rather than
459 :         // introducing a new case.
460 :         Node injectionPoint = ExpressionDecomposer.findInjectionPoint(callNode);
461 :         Preconditions.checkNotNull(injectionPoint);
462 :         Node injectionPointParent = injectionPoint.getParent();
463 :         Preconditions.checkNotNull(injectionPointParent);
464 :         Preconditions.checkState(
465 :             NodeUtil.isStatementBlock(injectionPointParent));
466 : 
467 :         // Declare the intermediate result name.
468 :         newBlock.addChildrenToFront(
469 :             NodeUtil.newVarNode(resultName, null)
470 :                  .copyInformationFromForTree(callNode));
471 :         // Inline the function before the selected injection point (before
472 :         // the call).
473 :         injectionPointParent.addChildBefore(newBlock, injectionPoint);
474 :         // Replace the call site with a reference to the intermediate
475 :         // result name.
476 :         parent.replaceChild(callNode, Node.newString(Token.NAME, resultName));
477 :         break;
478 : 
479 :       default:
480 :         throw new IllegalStateException("Unexpected call site type.");
481 :     }
482 : 
483 :     return newBlock;
484 :   }"

" 61 :   Node mutate(String fnName, Node fnNode, Node callNode,
 62 :       String resultName, boolean needsDefaultResult, boolean isCallInLoop) {
 63 :     Node newFnNode = fnNode.cloneTree();
 64 :     // Now that parameter names have been replaced, make sure all the local
 65 :     // names are unique, to allow functions to be inlined multiple times
 66 :     // without causing conflicts.
 67 :     makeLocalNamesUnique(newFnNode, isCallInLoop);
 68 : 
 69 :     // TODO(johnlenz): Mark NAME nodes constant for parameters that are not
 70 :     // modified.
 71 :     Set<String> namesToAlias =
 72 :         FunctionArgumentInjector.findModifiedParameters(newFnNode);
 73 :     LinkedHashMap<String, Node> args =
 74 :         FunctionArgumentInjector.getFunctionCallParameterMap(
 75 :             newFnNode, callNode, this.safeNameIdSupplier);
 76 :     boolean hasArgs = !args.isEmpty();
 77 :     if (hasArgs) {
 78 :       FunctionArgumentInjector.maybeAddTempsForCallArguments(
 79 :           newFnNode, args, namesToAlias, compiler.getCodingConvention());
 80 :     }
 81 : 
 82 :     Node newBlock = NodeUtil.getFunctionBody(newFnNode);
 83 :     // Make the newBlock insertable .
 84 :     newBlock.detachFromParent();
 85 : 
 86 :     if (hasArgs) {
 87 :       Node inlineResult = aliasAndInlineArguments(newBlock,
 88 :           args, namesToAlias);
 89 :       Preconditions.checkState(newBlock == inlineResult);
 90 :     }
 91 : 
 92 :     //
 93 :     // For calls inlined into loops, VAR declarations are not reinitialized to
 94 :     // undefined as they would have been if the function were called, so ensure
 95 :     // that they are properly initialized.
 96 :     //
 97 :     if (isCallInLoop) {
 98 :       fixUnitializedVarDeclarations(newBlock);
 99 :     }
100 : 
101 :     String labelName = getLabelNameForFunction(fnName);
102 :     Node injectableBlock = replaceReturns(
103 :         newBlock, resultName, labelName, needsDefaultResult);
104 :     Preconditions.checkState(injectableBlock != null);
105 : 
106 :     return injectableBlock;
107 :   }"

"170 :   private String getLabelNameForFunction(String fnName){
171 :     String name = (fnName == null || fnName.isEmpty()) ? "anon" : fnName;
172 :     return "JSCompiler_inline_label_" + name + "_" + safeNameIdSupplier.get();
173 :   }"

"256 :   private static Node replaceReturns(
257 :       Node block, String resultName, String labelName,
258 :       boolean resultMustBeSet) {
259 :     Preconditions.checkNotNull(block);
260 :     Preconditions.checkNotNull(labelName);
261 : 
262 :     Node root = block;
263 : 
264 :     boolean hasReturnAtExit = false;
265 :     int returnCount = NodeUtil.getNodeTypeReferenceCount(
266 :         block, Token.RETURN, new NodeUtil.MatchShallowStatement());
267 :     if (returnCount > 0) {
268 :       hasReturnAtExit = hasReturnAtExit(block);
269 :       // TODO(johnlenz): Simpler not to special case this,
270 :       // and let it be optimized later.
271 :       if (hasReturnAtExit) {
272 :         convertLastReturnToStatement(block, resultName);
273 :         returnCount--;
274 :       }
275 : 
276 :       if (returnCount > 0) {
277 :         // A label and breaks are needed.
278 : 
279 :         // Add the breaks
280 :         replaceReturnWithBreak(block, null, resultName, labelName);
281 : 
282 :         // Add label
283 :         Node label = new Node(Token.LABEL).copyInformationFrom(block);
284 :         Node name = Node.newString(Token.LABEL_NAME, labelName)
285 :             .copyInformationFrom(block);
286 :         label.addChildToFront(name);
287 :         label.addChildToBack(block);
288 : 
289 :         Node newRoot = new Node(Token.BLOCK).copyInformationFrom(block);
290 :         newRoot.addChildrenToBack(label);
291 : 
292 : 
293 :         // The label is now the root.
294 :         root = newRoot;
295 :       }
296 :     }
297 : 
298 :     // If there wasn't an return at the end of the function block, and we need
299 :     // a result, add one to the block.
300 :     if (resultMustBeSet && !hasReturnAtExit && resultName != null) {
301 :       addDummyAssignment(block, resultName);
302 :     }
303 : 
304 :     return root;
305 :   }"

